for (const key of ["window", "document", "Node", "Element", "HTMLElement", "Text", "Comment", "DocumentFragment", "MutationObserver", "requestAnimationFrame", "getComputedStyle"]) {
  if (dom.window[key] !== undefined) globalThis[key] = dom.window[key];
}
for (const name of ["App", "List"]) {
  const { js } = compile(readFileSync(`${name}.svelte`, "utf8"), { generate: "client", dev: true, filename: `${name}.svelte` });
  writeFileSync(`${name}.compiled.mjs`, js.code.replaceAll('"./List.svelte"', '"./List.compiled.mjs"'));
}
